import {records,categories} from './data.mjs';
import {search,normalize,explain,kindLabels} from './engine.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mode='assist',view='search',limit=12,revealApprox=false,previousQuery=null,currentMatches=[],session=null,taskStarted=0,queryTimer,announcementTimer;
const symbols={Tools:'⌘',Services:'◎',Resources:'▤',Places:'⌖',Forms:'▧'};
$('#category').innerHTML=categories.map(x=>`<option>${x}</option>`).join('');
function highlight(text,m){if(mode!=='assist'||$('#explanation-style').value==='off'||!$('#query').value.trim())return esc(text);const terms=[...new Set(m.evidence.flatMap(e=>[e.query,e.term]).filter(t=>t&&t.length>1))].sort((a,b)=>b.length-a.length);if(!terms.length)return esc(text);const rx=new RegExp('('+terms.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','ig');return String(text).split(rx).map((s,i)=>i%2?`<mark>${esc(s)}</mark>`:esc(s)).join('');}
function explanationHtml(m){if(mode!=='assist'||m.kind==='browse'||$('#explanation-style').value==='off')return '';const text=esc(explain(m));return `<div class="explanation">${$('#explanation-style').value==='demand'?`<details data-explain="${m.record.id}"><summary>Why this matched</summary>${text}</details>`:text}</div>`;}
function card(m){const r=m.record,approx=!['direct','browse'].includes(m.kind);return `<article class="result-card"><div class="card-top"><span class="card-symbol" aria-hidden="true">${symbols[r.category]}</span><div><div class="card-category">${r.category}</div><h3><button class="result-title" data-record="${r.id}">${highlight(r.title,m)}</button></h3></div><span class="card-arrow" aria-hidden="true">↗</span></div><p>${highlight(r.description,m)}</p><div class="card-bottom"><span class="tag">${esc(r.tags[0])}</span>${mode==='assist'&&m.kind!=='browse'&&$('#explanation-style').value!=='off'?`<span class="match-badge ${approx?'approx':''}">${kindLabels[m.kind]}</span>`:'<span class="tag">Directory entry</span>'}</div>${explanationHtml(m)}</article>`;}
function grid(ms){return `<div class="result-grid">${ms.map(card).join('')}</div>`;}
function empty(title,text,actions=''){return `<div class="empty"><h3>${title}</h3><p>${text}</p>${actions?`<div class="empty-actions">${actions}</div>`:''}</div>`;}
function updateSuggestion(ms){const box=$('#suggestion');box.hidden=true;if(mode!=='assist'||!$('#query').value.trim())return;if(previousQuery!==null){box.innerHTML=`Suggestion applied. <button id="undo-query">Undo</button>`;box.hidden=false;return;}
const first=ms[0];if(!first||first.kind!=='spelling'||first.coverage<1)return;
const changes=first.evidence.filter(e=>e.kind==='spelling');let proposed=normalize($('#query').value).split(' ').map(t=>changes.find(e=>e.query===t)?.term??t).join(' ');
if(proposed===normalize($('#query').value))return;
box.innerHTML=`<label for="suggested-query">Did you mean</label><input id="suggested-query" aria-label="Edit suggested query" value="${esc(proposed)}"><button id="apply-suggestion">Apply suggestion ↗</button><span class="sr-only">Your original query has not changed.</span>`;box.hidden=false;
}
function renderResults(){clearTimeout(announcementTimer);const q=$('#query').value;currentMatches=search(records,q,{mode,category:$('#category').value,field:$('#field').value,related:$('#related').checked});
const exact=currentMatches.filter(m=>m.kind==='direct'||m.kind==='browse'),approx=currentMatches.filter(m=>!['direct','browse'].includes(m.kind));
$('#results-heading').textContent=q.trim()?'Search results':'The directory';$('#result-count').textContent=`${currentMatches.length} ${q.trim()?(currentMatches.length===1?'match':'matches'):(currentMatches.length===1?'entry':'entries')}`;
$('#query-note').textContent=q.trim()?`Results for “${q}”`:'A small dataset. Room to explore.';
let content='';let visible=[];
if(mode==='assist'&&q.trim()){
 const directVisible=exact.slice(0,limit);visible.push(...directVisible);
 if(exact.length)content+=`<div class="group-heading">Direct matches <span>${exact.length} ${exact.length===1?'entry':'entries'} containing your words</span></div>`+grid(directVisible);
 else content+=empty('No direct matches. A few ways forward.','Your query is unchanged. You can edit it, try an approximate match, or browse the directory.',session?'':`<button class="secondary" data-action="browse">Browse all entries</button>${$('#category').value!=='All categories'||$('#field').value!=='all'?'<button class="secondary" data-action="reset-filters">Reset filters</button>':''}`);
 const pref=$('#approx-style').value;
 if(approx.length&&pref!=='none'){
  if(pref==='request'&&!revealApprox)content+=`<div class="load-row"><button class="secondary" data-action="reveal">Show ${approx.length} approximate ${approx.length===1?'match':'matches'}</button></div>`;
  else {const remaining=Math.max(0,limit-directVisible.length),av=approx.slice(0,remaining);visible.push(...av);if(av.length)content+=`<div class="group-heading">✦ Approximate matches <span>Related, partial, or close in spelling · ${approx.length} found</span></div>`+grid(av);}
 }
 if(!approx.length&&!exact.length)content+=`<div class="load-row"><p class="muted">Try a shorter query such as “calendar”, “library”, or “account”.</p></div>`;
 if(pref==='none'&&approx.length)content+=`<p class="small-print section-gap">${approx.length} approximate matches are hidden by your preference.</p>`;
}else{
 visible=currentMatches.slice(0,limit);content=visible.length?grid(visible):empty('No results found.','Try changing your search terms or browsing the directory.',session?'':'<button class="secondary" data-action="browse">Browse all entries</button>');
}
const maxVisible=mode==='assist'&&q.trim()?exact.length+(($('#approx-style').value==='none'||($('#approx-style').value==='request'&&!revealApprox))?0:approx.length):currentMatches.length;
if(maxVisible>visible.length)content+=`<div class="load-row"><button class="secondary" data-action="more">Show more entries <span>↓</span></button></div>`;
$('#results').innerHTML=content;$('#clear-query').hidden=!q;updateSuggestion(currentMatches);
announcementTimer=setTimeout(()=>{$('#status').textContent=`${currentMatches.length} matches found. ${visible.length} shown. ${mode==='assist'&&q.trim()?`${exact.length} direct and ${approx.length} approximate.`:''}`;},220);
}
function log(type,extra={}){if(!session||session.phase!=='tasks')return;session.events.push({taskIndex:session.taskIndex,condition:session.order[Math.floor(session.taskIndex/4)],type,elapsedMs:Math.round(performance.now()-taskStarted),...extra});saveSession();}
function changeQuery({from='typing'}={}){previousQuery=null;limit=12;revealApprox=false;renderResults();clearTimeout(queryTimer);if(session&&session.phase==='tasks'){const value=$('#query').value,at=Math.round(performance.now()-taskStarted);queryTimer=setTimeout(()=>{session.events.push({taskIndex:session.taskIndex,condition:session.order[Math.floor(session.taskIndex/4)],type:'query',elapsedMs:at,query:value,source:from});saveSession();},300);}}
$('#query').addEventListener('input',()=>changeQuery());
$('#search-form').addEventListener('submit',e=>{e.preventDefault();log('submit',{query:$('#query').value});renderResults();const first=$('#results .result-title');if(first)first.focus();});
$('#clear-query').onclick=()=>{$('#query').value='';changeQuery({from:'clear'});$('#query').focus();};
$$('[data-example]').forEach(b=>b.onclick=()=>{$('#query').value=b.dataset.example;changeQuery({from:'example'});$('#query').focus();});
function setMode(value){mode=value;$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});$('#options-toggle').hidden=mode!=='assist'||!!session&&session.phase==='tasks';$('#search-options').hidden=true;$('#options-toggle').setAttribute('aria-expanded','false');previousQuery=null;limit=12;revealApprox=false;renderResults();}
$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
$('#mode-info').onclick=()=>$('#info-dialog').showModal();
$('#options-toggle').onclick=()=>{const next=!$('#search-options').hidden;$('#search-options').hidden=next;$('#options-toggle').setAttribute('aria-expanded',String(!next));};
for(const id of ['category','field','related','explanation-style','approx-style'])$('#'+id).addEventListener('change',()=>{limit=12;revealApprox=false;previousQuery=null;log('options',{control:id,value:$('#'+id).type==='checkbox'?$('#'+id).checked:$('#'+id).value});renderResults();});
$('#suggestion').onclick=e=>{if(e.target.id==='apply-suggestion'){previousQuery=$('#query').value;$('#query').value=$('#suggested-query').value;log('suggestion_applied',{original:previousQuery,query:$('#query').value});limit=12;renderResults();$('#query').focus();}if(e.target.id==='undo-query'){const old=previousQuery;previousQuery=null;$('#query').value=old;log('suggestion_undone',{query:old});renderResults();$('#query').focus();}};
$('#results').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.record){openDetail(b.dataset.record);return;}switch(b.dataset.action){case'browse':$('#query').value='';$('#category').value='All categories';changeQuery({from:'browse'});$('#query').focus();break;case'reset-filters':$('#category').value='All categories';$('#field').value='all';renderResults();break;case'reveal':revealApprox=true;log('approximate_revealed');renderResults();break;case'more':limit+=12;renderResults();break;}};
$('#results').addEventListener('toggle',e=>{if(e.target.matches('details')&&e.target.open)log('explanation_opened',{recordId:e.target.dataset.explain});},true);
function openDetail(id){const m=currentMatches.find(x=>x.record.id===id);if(!m)return;const r=m.record;log('result_opened',{recordId:id,rank:currentMatches.indexOf(m)+1,query:$('#query').value});$('#detail-content').innerHTML=`<div class="eyebrow">${r.category.toUpperCase()} / DIRECTORY ENTRY</div><h2 id="detail-title">${highlight(r.title,m)}</h2><p>${esc(r.description)}</p><div class="detail-meta">${r.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${mode==='assist'&&m.kind!=='browse'&&$('#explanation-style').value!=='off'?`<div class="detail-section"><h3>Why this matched</h3><p>${esc(explain(m))}</p></div>`:''}<div class="detail-section"><h3>About this entry</h3><p>This is a synthetic entry in the SearchAssist study directory. It does not open an external service.</p></div>${session&&session.phase==='tasks'?`<button class="primary" id="submit-result" data-id="${id}">Submit this result →</button>`:''}`;$('#detail-dialog').showModal();const submit=$('#submit-result');if(submit)submit.onclick=()=>finishTask(id);}
$$('dialog').forEach(d=>{d.querySelector('.dialog-close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
document.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(tag)&&!$('dialog[open]')){e.preventDefault();location.hash='search';$('#query').focus();}if(e.key==='ArrowDown'&&document.activeElement===$('#query')){const first=$('#results .result-title');if(first){e.preventDefault();first.focus();return;}}if(['ArrowDown','ArrowUp'].includes(e.key)&&document.activeElement?.classList.contains('result-title')){const buttons=$$('#results .result-title'),index=buttons.indexOf(document.activeElement),next=e.key==='ArrowDown'?index+1:index-1;e.preventDefault();if(next<0)$('#query').focus();else buttons[Math.min(next,buttons.length-1)]?.focus();}if(e.key==='Escape'&&document.activeElement===$('#query')&&$('#query').value){$('#query').value='';changeQuery({from:'escape'});}});
function renderResearch(){$('#view-research').innerHTML=`<div class="page-heading"><div><div class="eyebrow"><span></span> LISTEN FIRST. DESIGN SECOND.</div><h1>Behind the search<span>.</span><p>What 26 survey responses tell us about searching,<br>getting stuck, and finding a way forward.</p></div><div class="heading-index">02 <span>/ RESEARCH</span></div></div><p class="research-lead">The survey informs the first design. It does not yet establish whether SearchAssist improves success, speed, understanding, or trust. Those are questions for the comparison study.</p><div class="metrics"><div class="metric"><div class="number">26</div><b>Survey responses</b><p>All 26 selected the adult consent option.</p></div><div class="metric"><div class="number">15<span class="muted"> / 26</span></div><b>Want editable suggestions</b><p>Selected this correction preference; multiple selections allowed.</p></div><div class="metric"><div class="number">21<span class="muted"> / 26</span></div><b>Prefer brief explanations</b><p>13 chose a short sentence; 8 a short label.</p></div></div><div class="research-grid"><div class="panel"><h2>What gets in the way?</h2><p>Top frustrations selected · multiple selections · n = 26</p>${[['Irrelevant results',15],['Only part of a name known',12],['No results returned',11],['Spelling mistakes',9],['Correct result ranked too low',5]].map(([t,n])=>`<div class="bar-item"><div class="bar-label"><span>${t}</span><b>${n} / 26 · ${Math.round(n/26*100)}%</b></div><div class="bar-track"><div class="bar-fill" style="width:${n/26*100}%"></div></div></div>`).join('')}</div><div class="panel"><h2>Control matters</h2><p>Different preferences deserve adjustable defaults.</p><div class="finding"><small>12 OF 26 RESPONDENTS</small><h3>Keep approximate matches separate</h3><p>Another 8 want them only when requested. The prototype supports both approaches.</p></div><div class="finding"><small>16 OF 26 RESPONDENTS</small><h3>Show the matching text</h3><p>Highlights use underlining as well as background color. Keyboard focus has its own outline.</p></div><div class="finding"><small>13 OF 26 RESPONDENTS</small><h3>Offer explanations on demand</h3><p>7 chose “Only when requested”; 6 chose a tooltip or information icon. Expandable text provides a keyboard-accessible option.</p></div></div></div><div class="panel section-gap"><h2>Evidence → first design decisions</h2><p>These are design interpretations, to be tested in the prototype.</p><table class="data-table"><thead><tr><th>Survey evidence</th><th>Prototype response</th></tr></thead><tbody><tr><td>15 / 26 selected editable suggestions</td><td>Propose a correction, let the user edit it, and provide Apply and Undo.</td></tr><tr><td>14 / 26 want to see which field matched</td><td>Explanations name the title, description, category, or tags supporting a result.</td></tr><tr><td>14 / 26 selected closest matches; 14 selected related terms</td><td>Offer bounded spelling recovery and explicit curated term relationships.</td></tr><tr><td>Synonym acceptance varies: 9 require application-defined terms; 6 say yes; 5 say it depends; 4 say no; 2 are unsure</td><td>Use a visible, manually curated alias and synonym list. No inferred semantic relationships.</td></tr><tr><td>24 / 26 use smartphones; 21 / 26 use laptops</td><td>Responsive layouts, touch targets, and full keyboard access.</td></tr></tbody></table></div><div class="panel section-gap"><h2>Three comparison conditions</h2><table class="data-table"><thead><tr><th>Condition</th><th>Matching</th><th>Interface</th></tr></thead><tbody><tr><td>A · Exact</td><td>Normalized literal phrase in searchable fields</td><td>Single result list without explanations</td></tr><tr><td>B · Fuzzy</td><td>Approximate words plus curated aliases and synonyms</td><td>Single ranked list without explanations</td></tr><tr><td>C · SearchAssist</td><td>Same engine and ranking as B</td><td>Highlighted evidence, short explanations, editable corrections, separated approximate matches</td></tr></tbody></table><p>The study compares interface bundles. Differences between B and C cannot be attributed to explanations alone.</p></div><div class="research-note"><strong>Research scope and data quality.</strong> Source: “Search Behavior, Failures, and Result Transparency (Responses).xlsx”, Form Responses 1, 26 response rows dated October 1–15, 2026. This is an exploratory convenience sample; recruitment and demographic representativeness are not established by the workbook. All submitted rows are retained; no formal response-quality screening has been applied. Multiple-choice selections may overlap.</div><div class="panel section-gap"><h2>Analysis notes</h2><p>One “Search problem” value appears in the word-order frequency column and one in the incorrect-correction frequency column. They are invalid frequency values and excluded from those item-level frequency distributions (valid n = 25 each). One malformed option in the top-frustrations question is excluded from option counts, with the respondent retained in the overall denominator. The truncated option “I only knew part of the nam” is normalized to “Only part of a name known.” Options containing commas are parsed as complete options, not split into separate answers.</p><p class="section-gap">The initial research phase uses this survey in place of the interviews proposed in the abstract. The prototype has not yet undergone a participant evaluation. Accessibility features are implemented for testing; assistive-technology conformance has not been independently verified.</p></div>`;}
const taskSets=[[
{type:'spelling',query:'calender',target:'calendar',prompt:'Find the tool for changing event reminders and calendar preferences.'},
{type:'alias',query:'NYC',target:'nyc',prompt:'Find the directory entry for the city with five boroughs.'},
{type:'partial',query:'official trans',target:'transcript',prompt:'Find the form for ordering an official record of courses and grades.'},
{type:'reordered',query:'portal tuition',target:'tuition',prompt:'Find the tool used to pay tuition charges.'}],
[{type:'spelling',query:'libary research',target:'library',prompt:'Find the tool for searching the library’s journal articles and research papers.'},
{type:'alias',query:'DMV',target:'dmv',prompt:'Find the department responsible for driver licenses and vehicle registration.'},
{type:'partial',query:'student hous',target:'housing',prompt:'Find the form for applying for campus accommodation.'},
{type:'reordered',query:'settings email',target:'email',prompt:'Find the tool for changing email forwarding and signatures.'}],
[{type:'spelling',query:'scholrship',target:'scholarships',prompt:'Find the resource listing scholarship eligibility and application dates.'},
{type:'alias',query:'MIT',target:'mit',prompt:'Find the Massachusetts institution focused on engineering and technology.'},
{type:'partial',query:'intern opp',target:'internship',prompt:'Find the resource listing internships for current students.'},
{type:'reordered',query:'schedule examination',target:'exam',prompt:'Find the resource containing exam dates, times, and room assignments.'}]
];
const orders=['ABC','ACB','BAC','BCA','CAB','CBA'],conditionModes={A:'exact',B:'fuzzy',C:'assist'};
const sessionKey='searchassist-study-v1';
function saveSession(){if(session){try{sessionStorage.setItem(sessionKey,JSON.stringify(session));}catch{}}}
function activeTask(){const block=Math.floor(session.taskIndex/4);return taskSets[(block+session.setRotation)%3][session.taskIndex%4];}
function studyView(){
const root=$('#view-study');
if(session?.phase==='ratings'){root.innerHTML=`<div class="eyebrow"><span></span> BLOCK ${Math.floor((session.taskIndex-1)/4)+1} OF 3 COMPLETE</div><h1>A quick reflection<span>.</span></h1><p class="research-lead">Rate the search experience you just used. There are no right answers.</p><form id="ratings-form" class="panel section-gap">${[['confidence','How confident were you that you found the requested entries?','Not at all confident','Very confident'],['trust','How much did you trust this search experience?','Not at all','Very much'],['ease','How easy was this search experience to use?','Very difficult','Very easy']].map(([id,t,lo,hi])=>`<fieldset class="rating-question"><legend>${t}</legend><div class="rating-row">${Array.from({length:7},(_,i)=>`<label><input type="radio" name="${id}" value="${i+1}" required> ${i+1}</label>`).join('')}</div><p class="small-print">1 = ${lo} · 7 = ${hi}</p></fieldset>`).join('')}<label class="small-print">Optional observation<textarea name="notes" rows="3" style="display:block;width:100%;border:1px solid #d7e1ce;border-radius:5px;padding:10px;margin:8px 0 20px" placeholder="What helped or got in the way?"></textarea></label><button class="primary">${session.taskIndex===12?'Finish session':'Continue to next block'} →</button></form>`;$('#ratings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),block=Math.floor((session.taskIndex-1)/4);session.ratings.push({condition:session.order[block],confidence:Number(f.get('confidence')),trust:Number(f.get('trust')),ease:Number(f.get('ease')),notes:f.get('notes')});if(session.taskIndex===12){session.phase='complete';session.finishedAt=new Date().toISOString();saveSession();studyView();}else{session.phase='tasks';beginTask();}};return;}
if(session?.phase==='complete'){const correct=session.trials.filter(t=>t.success).length;root.innerHTML=`<div class="eyebrow"><span></span> SESSION COMPLETE</div><h1>Ready to reflect<span>.</span></h1><p class="research-lead">Your session is stored in this tab until you clear it or close the tab. Export it before leaving.</p><div class="metrics"><div class="metric"><div class="number">${correct} / 12</div><b>Correct final selections</b><p>Task success against the predefined target.</p></div><div class="metric"><div class="number">${session.order}</div><b>Condition order</b><p>A Exact · B Fuzzy · C SearchAssist</p></div><div class="metric"><div class="number">${Math.round(session.trials.reduce((s,t)=>s+t.elapsedMs,0)/1000)}s</div><b>Total task time</b><p>Includes time spent looking at result details.</p></div></div><div class="panel"><h2>Session results</h2><table class="data-table"><thead><tr><th>Condition</th><th>Success</th><th>Mean time</th><th>Query edits</th><th>Trust / 7</th></tr></thead><tbody>${['A','B','C'].map(c=>{const t=session.trials.filter(t=>t.condition===c),r=session.ratings.find(r=>r.condition===c);return `<tr><td>${c} · ${conditionModes[c]}</td><td>${t.filter(t=>t.success).length} / ${t.length}</td><td>${(t.reduce((s,t)=>s+t.elapsedMs,0)/t.length/1000).toFixed(1)} s</td><td>${t.reduce((s,t)=>s+t.queryReformulations,0)}</td><td>${r?.trust??'—'}</td></tr>`;}).join('')}</tbody></table><p class="small-print">A single exploratory session does not establish comparative effectiveness. Query edits count changes after the prefilled starting query, coalesced at 300 ms. Ratings are custom single items, not a validated usability scale.</p>${exportButtons()}</div>`;bindExports();return;}
root.innerHTML=`<div class="page-heading"><div><div class="eyebrow"><span></span> TURN A PROTOTYPE INTO EVIDENCE</div><h1>Put search to the test<span>.</span></h1><p>A guided, within-subject comparison of three search experiences.</p></div><div class="heading-index">03 <span>/ STUDY</span></div></div>${session?.phase==='tasks'?`<div class="panel"><h2>You have a session in progress</h2><p>Task ${session.taskIndex+1} of 12. Returning resumes the current trial; a page reload restarts its timer and flags the trial as restarted.</p><div class="export-actions"><button id="resume-session" class="primary">Resume session →</button></div>${exportButtons()}</div>`:`<div class="study-intro"><div class="panel"><h2>The session at a glance</h2><div class="step"><span>1</span><div><h3>Choose an order and task rotation</h3><p>Use the six condition orders evenly across participants. Rotate three matched task sets independently.</p></div></div><div class="step"><span>2</span><div><h3>Complete 12 directory tasks</h3><p>Four tasks per condition: misspelling, abbreviation, incomplete words, and reordered words. Edit the supplied query as needed, open an entry, then submit a result or skip.</p></div></div><div class="step"><span>3</span><div><h3>Reflect and export</h3><p>Rate confidence, trust, and ease after each block. Export trial results as CSV and the event log as JSON.</p></div></div><p class="small-print">Facilitator note: run a separate practice task before collecting data. For formal research, obtain any required course or institutional approval and consent. Do not enter names or contact details.</p></div><form class="panel setup-form" id="start-study"><h2>Set up a session</h2><label>Anonymous participant code<input id="participant-code" maxlength="32" required placeholder="e.g. P001" pattern="[A-Za-z0-9_-]+" title="Use letters, numbers, underscores, or hyphens"></label><label>Condition order<select id="condition-order">${orders.map(o=>`<option value="${o}">${o.split('').join(' → ')}</option>`).join('')}</select></label><label>Task set rotation<select id="set-rotation"><option value="0">1 → 2 → 3</option><option value="1">2 → 3 → 1</option><option value="2">3 → 1 → 2</option></select></label><p class="small-print">This prototype records queries, selections, task times, skips, explanation opens, and ratings in this browser tab. No study responses are sent to a server. Exports may contain what you type. The app does not suppress ordinary hosting access logs.</p><label class="checkline"><input type="checkbox" required><span>I agree to this local session recording and understand that I can stop and clear it.</span></label><button class="primary">Start study session →</button></form></div>`}<div class="panel section-gap"><h2>How to interpret the comparison</h2><p>Condition B and C share their matching engine and ranking. Study settings are held constant: all fields, all categories, curated relationships enabled. C adds several recovery and explanation features together. The task sets are matched by query type but have not been validated for equal difficulty. The starting queries intentionally include errors; findings should be limited to these controlled tasks.</p><p class="section-gap">Record observations separately if using think-aloud. Talking can change completion times; use the same instruction across conditions. A future study should measure explanation comprehension and use a validated usability questionnaire if claiming usability scores.</p></div>`;
if($('#start-study'))$('#start-study').onsubmit=e=>{e.preventDefault();session={version:'0.1',datasetVersion:'synthetic-directory-v1',participant:$('#participant-code').value,order:$('#condition-order').value,setRotation:Number($('#set-rotation').value),startedAt:new Date().toISOString(),phase:'tasks',taskIndex:0,trials:[],ratings:[],events:[]};beginTask();};
if($('#resume-session'))$('#resume-session').onclick=()=>{beginTask();};bindExports();}
function beginTask({restarted=false}={}){clearTimeout(queryTimer);const t=activeTask();mode=conditionModes[session.order[Math.floor(session.taskIndex/4)]];$('#query').value=t.query;$('#category').value='All categories';$('#field').value='all';$('#related').checked=true;$('#explanation-style').value='short';$('#approx-style').value='separate';session.currentRestarted=restarted||session.currentRestarted||session.events.some(e=>e.taskIndex===session.taskIndex&&e.type==='task_started');taskStarted=performance.now();setMode(mode);$('#examples').hidden=true;$('.mode-row').hidden=true;$('.filter-row').hidden=true;$('#study-banner').hidden=false;$('.bottom-note').hidden=true;$('#study-banner').innerHTML=`<div class="study-task-top"><span class="tiny-cap">STUDY · TASK ${session.taskIndex+1} OF 12</span><span class="study-progress">Block ${Math.floor(session.taskIndex/4)+1} of 3 · ${session.order[Math.floor(session.taskIndex/4)]}</span></div><h2>${t.prompt}</h2><p>The starting query is supplied. Change it as needed, open a result, and submit your choice.</p><div class="study-task-actions"><button class="secondary" id="skip-task">Skip task</button><button class="text-btn" id="stop-session">End session & clear data</button></div>`;$('#skip-task').onclick=()=>finishTask(null);$('#stop-session').onclick=clearData;log('task_started',{startingQuery:t.query,restarted:session.currentRestarted});saveSession();location.hash='search';route();$('#query').focus();}
function finishTask(selected){clearTimeout(queryTimer);const t=activeTask(),condition=session.order[Math.floor(session.taskIndex/4)];const events=session.events.filter(e=>e.taskIndex===session.taskIndex);const edits=events.filter(e=>['query','suggestion_applied','suggestion_undone'].includes(e.type)).map(e=>e.query);if($('#query').value!==(edits.at(-1)??t.query))edits.push($('#query').value);let last=t.query;const queries=edits.filter(q=>{if(q===last)return false;last=q;return true;});session.trials.push({taskIndex:session.taskIndex+1,condition,taskSet:(Math.floor(session.taskIndex/4)+session.setRotation)%3+1,queryType:t.type,targetId:t.target,selectedId:selected,success:selected===t.target,skipped:selected===null,elapsedMs:Math.round(performance.now()-taskStarted),initialQuery:t.query,finalQuery:$('#query').value,queryReformulations:queries.length,resultOpens:events.filter(e=>e.type==='result_opened').length,incorrectResultOpens:events.filter(e=>e.type==='result_opened'&&e.recordId!==t.target).length,incorrectFinalSelection:selected!==null&&selected!==t.target,restarted:!!session.currentRestarted});session.taskIndex++;session.currentRestarted=false;$('#detail-dialog').close();if(session.taskIndex%4===0){session.phase='ratings';endTaskUI();saveSession();location.hash='study';studyView();route();}else beginTask();}
function endTaskUI(){$('#study-banner').hidden=true;$('.bottom-note').hidden=false;$('#examples').hidden=false;$('.mode-row').hidden=false;$('.filter-row').hidden=false;}
function clearData(){if(!confirm('Clear this session and its local recordings? Export first if you need to keep them.'))return;clearTimeout(queryTimer);session=null;try{sessionStorage.removeItem(sessionKey);}catch{}endTaskUI();$('#query').value='';setMode('assist');location.hash='study';studyView();}
function exportButtons(){return `<div class="export-actions"><button class="primary" id="export-json">Export session JSON ↓</button><button class="secondary" id="export-csv">Export trials CSV ↓</button><button class="text-btn" id="clear-session">Clear session data</button></div>`;}
function download(content,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindExports(){if($('#export-json'))$('#export-json').onclick=()=>download(JSON.stringify(session,null,2),`searchassist-${session.participant}.json`,'application/json');if($('#export-csv'))$('#export-csv').onclick=()=>{const keys=['participant','order','taskIndex','condition','taskSet','queryType','targetId','selectedId','success','skipped','elapsedMs','initialQuery','finalQuery','queryReformulations','resultOpens','incorrectResultOpens','incorrectFinalSelection','restarted','confidence','trust','ease'];const safe=v=>{let x=String(v??'');if(/^[=+@\-\t\r]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"';};const rows=session.trials.map(t=>({...t,participant:session.participant,order:session.order,...session.ratings.find(r=>r.condition===t.condition)}));download([keys.map(safe).join(','),...rows.map(r=>keys.map(k=>safe(r[k])).join(','))].join('\r\n'),`searchassist-${session.participant}-trials.csv`,'text/csv');};if($('#clear-session'))$('#clear-session').onclick=clearData;}
function route(){if(location.hash==='#main')return;view=location.hash.slice(1)||'search';if(!['search','research','study'].includes(view))view='search';if(session?.phase==='tasks'&&view!=='search'){view='study';}$$('.view').forEach(s=>s.hidden=s.id!==`view-${view}`);$$('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb').innerHTML=`Workspace <b>/</b> ${{search:'Explore search',research:'Research & insights',study:'Run a study'}[view]}`;if(view==='study')studyView();if(view==='research')renderResearch();}
window.addEventListener('hashchange',route);
try{const saved=JSON.parse(sessionStorage.getItem(sessionKey));if(saved?.version==='0.1'&&['tasks','ratings','complete'].includes(saved.phase))session=saved;}catch{}
setMode('assist');renderResearch();route();if(session?.phase==='tasks'){session.currentRestarted=true;location.hash='study';route();}
